GeometryBytes.source:
@dataclass(frozen=True)
class GeometryBytes:
    vertex_count: int
    polygon_count: int
    loop_count: int
    vertices: bytes
    starts: bytes
    sizes: bytes
    indices: bytes

    def polygons(self):
        starts = np.frombuffer(self.starts, dtype='<i8')
        sizes = np.frombuffer(self.sizes, dtype='<i8')
        indices = np.frombuffer(self.indices, dtype='<i8')
        return [indices[start:start + size].tolist() for start, size in zip(starts, sizes)]

    def digests(self):
        return {'float64_le_vertices_sha256': hashlib.sha256(self.vertices).hexdigest(), 'int64_le_topology_sha256': hashlib.sha256(self.starts + self.sizes + self.indices).hexdigest()}

atom.source:
def atom(v):
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    if isinstance(v, bpy.types.ID):
        return {'id_type': type(v).__name__, 'name': v.name}
    try:
        return [atom(x) for x in v]
    except TypeError:
        return str(v)

