mismatches = []
maximum = 0.0
checked = 0
rows = []
for f, wanted in zip(FRAMES, expected['samples']):
    set_frame(f)
    actual = {b.name: mat(A.matrix_world @ b.matrix @ rest[b.name].inverted()) for b in A.pose.bones}
    require(set(actual) == set(wanted['deformation_world']) and len(actual) == 148, 'control bone coverage differs')
    for name, m in actual.items():
        for i in range(4):
            for j in range(4):
                x = wanted['deformation_world'][name][i][j]
                y = m[i][j]
                checked += 1
                maximum = max(maximum, abs(x - y))
                if struct.pack('<d', x) != struct.pack('<d', y):
                    mismatches.append({'source_frame': f, 'bone': name, 'row': i, 'column': j, 'full': x, 'bounded': y, 'difference': y - x})
    focus = {}
    for name in wanted['focus_bones']:
        b = A.pose.bones[name]
        local = b.parent.matrix.inverted() @ b.matrix if b.parent else b.matrix
        loc, rot, scale = local.decompose()
        focus[name] = {'parent': b.parent.name if b.parent else None, 'rotation_mode': b.rotation_mode, 'location': list(b.location), 'rotation_quaternion': list(b.rotation_quaternion), 'rotation_euler': list(b.rotation_euler), 'scale': list(b.scale), 'matrix_basis': mat(b.matrix_basis), 'pose_parent_relative': mat(local), 'pose_parent_relative_decomposition': {'location': list(loc), 'rotation_quaternion': list(rot), 'scale': list(scale)}}

    def compare_values(x, y, path):
        if isinstance(x, dict):
            require(set(x) == set(y), 'focus channel structure differs')
            for key in x:
                compare_values(x[key], y[key], path + '/' + key)
        elif isinstance(x, list):
            require(len(x) == len(y), 'focus channel length differs')
            for i, (a0, b0) in enumerate(zip(x, y)):
                compare_values(a0, b0, path + '/' + str(i))
        elif isinstance(x, float):
            if struct.pack('<d', x) != struct.pack('<d', y):
                mismatches.append({'source_frame': f, 'focus_channel': path, 'full': x, 'bounded': y, 'difference': y - x})
        elif x != y:
            mismatches.append({'source_frame': f, 'focus_channel': path, 'full': x, 'bounded': y})
    compare_values(wanted['focus_bones'], focus, 'focus_bones')
    rows.append({'source_frame': f, 'deformation_world': actual, 'focus_bones': focus})

canonical_buffers.source:
def canonical_buffers(vertices, starts, sizes, indices):
    vertices = np.asarray(vertices, dtype='<f8', order='C')
    if vertices.ndim != 2 or vertices.shape[1] != 3 or len(vertices) == 0 or (not np.isfinite(vertices).all()):
        raise ValueError('invalid/nonfinite rigid coordinates')
    values = []
    for original in (starts, sizes, indices):
        array = np.asarray(original)
        if array.ndim != 1 or array.dtype.kind not in 'iu' or (array < 0).any() or (array > 2 ** 62).any():
            raise ValueError('invalid rigid integer topology')
        values.append(np.asarray(array, dtype='<i8', order='C'))
    starts, sizes, indices = values
    if len(starts) == 0 or len(starts) != len(sizes) or (sizes < 3).any() or (len(indices) == 0):
        raise ValueError('invalid rigid polygon layout')
    expected = np.concatenate((np.array([0], dtype='<i8'), np.cumsum(sizes[:-1], dtype='<i8')))
    if not np.array_equal(starts, expected) or int(sizes.sum()) != len(indices) or (indices >= len(vertices)).any():
        raise ValueError('invalid rigid loop/index coverage')
    return GeometryBytes(len(vertices), len(starts), len(indices), vertices.tobytes(order='C'), starts.tobytes(order='C'), sizes.tobytes(order='C'), indices.tobytes(order='C'))

