def extra_snapshot():
    meshes = {}
    for m in bpy.data.meshes:
        value = {'vertices': [list(v.co) for v in m.vertices], 'edges': [list(e.vertices) for e in m.edges], 'polygons': [{'vertices': list(p.vertices), 'material_index': p.material_index, 'use_smooth': p.use_smooth} for p in m.polygons], 'uv': {l.name: [list(v.uv) for v in l.data] for l in m.uv_layers}, 'materials': [x.name if x else None for x in m.materials]}
        meshes[m.name] = {'sha256': digest(value), 'vertices': len(m.vertices), 'polygons': len(m.polygons)}
    armatures = {}
    for a in bpy.data.armatures:
        val = [{'name': b.name, 'parent': b.parent.name if b.parent else None, 'rest_matrix': matrix(b.matrix_local), 'use_deform': b.use_deform, 'use_connect': b.use_connect, 'inherit_scale': b.inherit_scale, 'head': list(b.head_local), 'tail': list(b.tail_local)} for b in a.bones]
        armatures[a.name] = {'sha256': digest(val), 'bones': len(val), 'deform_order': [b.name for b in a.bones if b.use_deform]}
    objects = {}
    for o in bpy.data.objects:
        v = {'type': o.type, 'data': o.data.name if o.data else None, 'parent': o.parent.name if o.parent else None, 'parent_type': o.parent_type, 'parent_bone': o.parent_bone, 'matrix_parent_inverse': matrix(o.matrix_parent_inverse), 'modifiers': [{'type': m.type, 'props': props(m)} for m in o.modifiers], 'constraints': [{'type': c.type, 'props': props(c)} for c in o.constraints], 'vertex_groups': [g.name for g in o.vertex_groups]}
        if o.type == 'MESH':
            v['weights'] = [[(g.group, g.weight) for g in vert.groups] for vert in o.data.vertices]
        if o.pose:
            v['pose_constraints'] = {b.name: [{'type': c.type, 'props': props(c)} for c in b.constraints] for b in o.pose.bones}
        objects[o.name] = {'sha256': digest(v), 'type': o.type, 'data': v['data']}
    materials = {}
    for m in bpy.data.materials:
        val = {'diffuse_color': list(m.diffuse_color), 'use_nodes': m.use_nodes}
        if m.node_tree:
            val['nodes'] = [{'name': n.name, 'type': n.bl_idname, 'image': n.image.name if hasattr(n, 'image') and n.image else None, 'inputs': [(x.name, atom(x.default_value)) for x in n.inputs if hasattr(x, 'default_value')]} for n in m.node_tree.nodes]
            val['links'] = [(l.from_node.name, l.from_socket.name, l.to_node.name, l.to_socket.name) for l in m.node_tree.links]
        materials[m.name] = digest(val)
    actions_extended = {a.name: digest([{'data_path': f.data_path, 'index': f.array_index, 'extrapolation': f.extrapolation, 'mute': f.mute, 'modifiers': [props(m) for m in f.modifiers], 'key_handle_types': [(k.handle_left_type, k.handle_right_type, k.easing) for k in f.keyframe_points]} for f in a.fcurves]) for a in bpy.data.actions}
    pose_channels = {o.name: {b.name: {'rotation_mode': b.rotation_mode, 'location': list(b.location), 'rotation_euler': list(b.rotation_euler), 'rotation_quaternion': list(b.rotation_quaternion), 'rotation_axis_angle': list(b.rotation_axis_angle), 'scale': list(b.scale), 'custom_properties': {k: atom(b[k]) for k in b.keys() if k != '_RNA_UI'}} for b in o.pose.bones} for o in bpy.data.objects if o.pose}
    return {'actions_metadata': {a.name: {'use_fake_user': a.use_fake_user, 'properties': {k: atom(a[k]) for k in a.keys()}} for a in bpy.data.actions}, 'pose_channel_defaults': pose_channels, 'actions_extended': actions_extended, 'meshes': meshes, 'armatures': armatures, 'objects_and_bindings': objects, 'materials': materials, 'cameras': {c.name: digest(props(c)) for c in bpy.data.cameras}}

geometry_record.source:
def geometry_record(vertices, polygons):
    if not vertices or any((len(v) != 3 or any((not math.isfinite(c) for c in v)) for v in vertices)):
        raise ValueError('invalid/empty rigid local vertices')
    if not polygons or any((len(p) < 3 or any((type(i) is not int or i < 0 or i >= len(vertices) for i in p)) for p in polygons)):
        raise ValueError('invalid/empty rigid polygons')
    content = {'vertices_local': vertices, 'polygons': polygons}
    encoded = json.dumps(content, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
    return {**content, 'vertex_count': len(vertices), 'polygon_count': len(polygons), 'geometry_sha256': hashlib.sha256(encoded).hexdigest()}

linear_value.source:
def linear_value(times, values, f):
    i = bisect.bisect_left(times, f)
    if i < len(times) and times[i] == f:
        return values[i]
    require(0 < i < len(times), 'sample outside interpolation coverage')
    a, b = times[i - 1:i + 1]
    v, w = values[i - 1:i + 1]
    return v + (w - v) * ((f - a) / (b - a))

mesh_samples.source:
def mesh_samples(dg):
    samples = {}
    topology = {}
    for name in SKINS:
        obj = bpy.data.objects[name].evaluated_get(dg)
        mesh = obj.to_mesh()
        try:
            local = np.empty(len(mesh.vertices) * 3, dtype=np.float64)
            mesh.vertices.foreach_get('co', local)
            local = local.reshape(-1, 3)
            M = np.asarray(obj.matrix_world, dtype=np.float64)
            world = local @ M[:3, :3].T + M[:3, 3]
            assert np.isfinite(world).all()
            samples[name] = world
            topology[name] = {'vertices': len(mesh.vertices), 'edges': len(mesh.edges), 'polygons': len(mesh.polygons)}
        finally:
            obj.to_mesh_clear()
    return (samples, topology)

