def nla_snapshot(bpy):
    result = {}
    for obj in bpy.data.objects:
        data = obj.animation_data
        if data is None:
            continue
        result[obj.name] = {'action': data.action.name if data.action else None, 'use_nla': data.use_nla, 'tracks': [{'name': track.name, 'mute': track.mute, 'is_solo': track.is_solo, 'strips': [{'name': strip.name, 'action': strip.action.name if strip.action else None, **{key: getattr(strip, key) for key in ('frame_start', 'frame_end', 'action_frame_start', 'action_frame_end', 'scale', 'repeat', 'blend_type', 'extrapolation', 'influence', 'mute', 'use_auto_blend', 'blend_in', 'blend_out')}} for strip in track.strips]} for track in data.nla_tracks]}
    return result

operator_defaults.source:
def operator_defaults(properties):
    result = {}
    for prop in properties:
        if prop.identifier in ('rna_type', 'check_existing', 'filter_glob', 'ui_tab'):
            continue
        require(prop.type in ('BOOLEAN', 'INT', 'FLOAT', 'STRING', 'ENUM'), 'unexpected exporter RNA property: ' + prop.identifier)
        if prop.type == 'ENUM' and prop.is_enum_flag:
            value = set(prop.default_flag)
        elif getattr(prop, 'is_array', False):
            value = tuple(prop.default_array)
        else:
            value = prop.default
        result[prop.identifier] = value
    return result

props.source:
def props(obj):
    out = {}
    for p in obj.bl_rna.properties:
        k = p.identifier
        if k == 'rna_type' or p.type == 'COLLECTION' or p.is_readonly:
            continue
        try:
            out[k] = atom(getattr(obj, k))
        except (AttributeError, TypeError, ValueError):
            pass
    return out

